import express from "express";
import { createServer as createViteServer } from "vite";
import path from "path";
import fs from "fs";

async function startServer() {
  const app = express();
  const PORT = 3000;
  
  app.use(express.json());
  
  // Request logging
  app.use((req, res, next) => {
    console.log(`${new Date().toISOString()} - ${req.method} ${req.url}`);
    next();
  });

  // Health check
  app.get("/api/health", (req, res) => {
    res.json({ status: "ok", timestamp: new Date().toISOString() });
  });

  // Automatic Order Notification Endpoint
  app.post("/api/notify-order", async (req, res) => {
    try {
      const { venueName, orderedBy, deliveryDate, items, notes, isAddition } = req.body;
      
      // Construct text message
      const orderText = `🍞 *New Order Placed - MCN Bakery*\n` +
        `----------------------------------\n` +
        `🏢 *Venue:* ${venueName}\n` +
        `👤 *Ordered By:* ${orderedBy}\n` +
        `📅 *Delivery Date:* ${deliveryDate}\n` +
        `📝 *Special Notes:* ${notes || 'None'}\n\n` +
        `📦 *Order Breakdown:*\n` +
        items.map((item: any) => `• *${item.quantity}x* ${item.name}`).join('\n') + `\n\n` +
        `🔗 *Bakery Portal:* https://mcnbake.com`;

      const logs: string[] = [];
      let success = false;

      // 1. Webhook Notification (e.g. Zapier, Make, IFTTT)
      const webhookUrl = process.env.NOTIFICATION_WEBHOOK_URL;
      if (webhookUrl) {
        try {
          logs.push(`Attempting webhook notification to: ${webhookUrl}`);
          const response = await fetch(webhookUrl, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              event: "order_created",
              text: orderText,
              venueName,
              orderedBy,
              deliveryDate,
              items,
              notes,
              isAddition
            })
          });
          if (response.ok) {
            success = true;
            logs.push("Webhook notification sent successfully!");
          } else {
            logs.push(`Webhook returned status: ${response.status}`);
          }
        } catch (err: any) {
          logs.push(`Webhook error: ${err.message}`);
        }
      }

      // 2. UltraMsg Gateway
      const gatewayProvider = process.env.WHATSAPP_GATEWAY_PROVIDER || 'ultramsg';
      const apiKey = process.env.WHATSAPP_API_KEY;
      const instanceId = process.env.WHATSAPP_INSTANCE_ID;
      const recipient = process.env.WHATSAPP_RECIPIENT_NUMBER || '447745724611';

      if (apiKey && instanceId && gatewayProvider === 'ultramsg') {
        try {
          logs.push(`Attempting UltraMsg notification to: ${recipient}`);
          const response = await fetch(`https://api.ultramsg.com/${instanceId}/messages/chat`, {
            method: "POST",
            headers: { "Content-Type": "application/x-www-form-urlencoded" },
            body: new URLSearchParams({
              token: apiKey,
              to: recipient,
              body: orderText
            })
          });
          
          const resData = await response.json() as any;
          if (response.ok && (resData.sent === "true" || resData.success)) {
            success = true;
            logs.push("UltraMsg notification sent successfully!");
          } else {
            logs.push(`UltraMsg failed: ${JSON.stringify(resData)}`);
          }
        } catch (err: any) {
          logs.push(`UltraMsg error: ${err.message}`);
        }
      }

      if (!webhookUrl && (!apiKey || !instanceId)) {
        logs.push("Automatic notifications not fully configured in environment variables. Falling back to manual client-side sending.");
      }

      res.json({ success, logs });
    } catch (error: any) {
      console.error("Error sending automatic order notification:", error);
      res.status(500).json({ success: false, error: error.message });
    }
  });

  // Client side runtime error reporting
  app.post("/api/client-error", (req, res) => {
    const errorDetails = `====================== CLIENT RUNTIME CRASH REPORT ======================\n` +
      `TIME: ${new Date().toISOString()}\n` +
      `MESSAGE: ${req.body.message}\n` +
      `TYPE: ${req.body.type || 'onload-error'}\n` +
      `SOURCE: ${req.body.source || 'unknown'}\n` +
      `LINE: ${req.body.lineno} COL: ${req.body.colno}\n` +
      `STACK: ${req.body.stack || 'No stack trace'}\n` +
      `=========================================================================\n`;
    
    console.error(errorDetails);
    try {
      fs.appendFileSync(path.join(process.cwd(), "client_errors.txt"), errorDetails);
    } catch (e) {
      console.error("Failed to write to client_errors.txt:", e);
    }
    res.json({ captured: true });
  });

  // Vite middleware for development (or as fallback if dist is missing)
  const isProduction = process.env.NODE_ENV === "production";
  const distPath = path.join(process.cwd(), "dist");
  const hasDist = fs.existsSync(distPath);

  if (!isProduction || !hasDist) {
    if (isProduction && !hasDist) {
      console.warn("Production mode detected but 'dist' directory is missing. Falling back to Vite middleware.");
    }
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    app.use(express.static(distPath));
    app.get("*", (req, res) => {
      res.sendFile(path.join(distPath, "index.html"));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Server running on http://localhost:${PORT}`);
  });
}

startServer();
